 sources=[oldp,magep,catp,custom,life,R/'data/public/class_playtests/wizard.json',R/'data/public/class_playtests/ranger.json',R/'docs/mechanics/CREATURE_LIFECYCLE_PLAYTEST.md',R/'docs/mechanics/CHARACTER_CREATION_PLAYTEST.md',R/'docs/mechanics/CHARACTER_FOUNDATION_TABLES.md',R/'docs/mechanics/DAMAGE_SHARING_PLAYTEST.md']
 checks=[{'check':'Mage10 legal rank4','passed':mage['maxSpellRankByClassLevel'][9]>=4},{'check':'Mage10 pool29 and cost7','passed':mage['rpByClassLevel'][9]==29 and 29-7==22},{'check':'Actual undying minimum10','passed':mage['cards'][42]['minimumClassLevel']==10},{'check':'Mage fixed HP62','passed':6+2+9*(4+2)==62},{'check':'Original sphere6then13 damages Beast36to17','passed':36-13//2-13==17},{'check':'Ray hit and bounded actual HP loss','passed':15+6>=12 and min(6,5)==5},{'check':'Both CON20 succeeds DC10','passed':18+2>=10},{'check':'Original text retained','passed':fixture['originalTextUnchanged'].startswith('EV4-08-B:')}]
